const std = @import("std"); const mockm = @import("te-mock-page.zig"); const chro = @import("nt-brow-chro.zig"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig"); const inpu = @import("ru-huma-inpu.zig"); const cfgz = @import("cf-conf-load.zig"); const stat = @import("st-stat-main.zig"); const task = @import("ru-task-runn.zig");
const CF = .{ .boot = 30000, .wsmx = 15000, .conn = 8000, .step = 40000 };
pub const Rig = struct { allo: std.mem.Allocator, iozz: std.Io, tmpz: std.testing.TmpDir, mock: mockm.Mock, brow: chro.Brow, page: pg.Page, aren: std.heap.ArenaAllocator, rng: pace.Rng, conf: cfgz.Conf, store: stat.Stat, sink: std.ArrayList(u8) = .empty, bseu: [64]u8 = undefined, bsel: usize = 0,
pub fn up(self: *Rig) !void { self.allo = std.testing.allocator; self.iozz = std.testing.io; const exe = (try chro.exeFind(self.allo, self.iozz, "")) orelse return error.SkipZigTest; defer self.allo.free(exe); self.tmpz = std.testing.tmpDir(.{}); errdefer self.tmpz.cleanup(); try self.mock.start(self.iozz); errdefer self.mock.halt(); var prof: [128]u8 = undefined; const proz = try std.fmt.bufPrint(&prof, ".zig-cache/tmp/{s}/prof", .{self.tmpz.sub_path}); self.brow = try chro.launch(self.allo, self.iozz, exe, proz, true, CF.boot); errdefer self.brow.stop(); const wsp = try chro.pageWs(self.allo, self.iozz, self.brow.port, CF.wsmx); defer self.allo.free(wsp); self.page = try pg.pageOpen(self.allo, self.iozz, self.brow.port, wsp, CF.conn); errdefer self.page.closeConn(); self.aren = std.heap.ArenaAllocator.init(self.allo); errdefer self.aren.deinit(); self.rng = pace.Rng.init(11); self.conf = .{}; self.conf.time_scal_perc = 0; self.conf.acti_dely_secs = .{ 0, 0 }; self.conf.quie_hour_rang = .{ 0, 0 }; self.conf.warm_dayz_coun = 0; self.sink = .empty; self.conf.mous_step_coun = 4; self.page.arm(CF.step); try self.page.enable(self.aren.allocator()); var dbp: [128]u8 = undefined; const dbz = try std.mem.printSentinel(&dbp, ".zig-cache/tmp/{s}/or-state.db", .{self.tmpz.sub_path}, 0); self.store = try stat.Stat.open(self.allo, dbz); errdefer self.store.close(); try self.store.metaSet("consent", 1); const bse = self.mock.urlOf(&self.bseu, ""); self.bsel = bse.len; self.conf.base_appz_main = self.bseu[0..self.bsel]; self.conf.base_urlz_main = self.bseu[0..self.bsel]; self.conf.base_docz_main = self.bseu[0..self.bsel]; }
pub fn down(self: *Rig) void { self.store.close(); self.aren.deinit(); self.page.closeConn(); self.brow.stop(); self.mock.halt(); self.tmpz.cleanup(); }
pub fn base(self: *Rig) []const u8 { return self.bseu[0..self.bsel]; }
pub fn env(self: *Rig) inpu.Env { return .{ .page = &self.page, .rng = &self.rng, .conf = self.conf, .aren = self.aren.allocator() }; }
pub fn ctx(self: *Rig, mode: task.Mode) task.Ctx { return .{ .gpaz = self.allo, .aren = self.aren.allocator(), .iozz = self.iozz, .conf = self.conf, .store = &self.store, .mode = mode, .page = &self.page, .rng = &self.rng, .base = self.base(), .sink = &self.sink, .secr_user = "tester@example.com", .secr_pass = "pw-secret-1" }; }
pub fn go(self: *Rig, path: []const u8) !void { self.page.arm(CF.step); var buf: [160]u8 = undefined; const urlz = try std.fmt.bufPrint(&buf, "{s}{s}", .{ self.base(), path }); try self.page.navigate(self.aren.allocator(), urlz); }
pub fn hasRec(self: *Rig, prefix: []const u8) bool { var ix: usize = 0; while (ix < self.mock.recCnt()) : (ix += 1) { if (std.mem.startsWith(u8, self.mock.recAt(ix), prefix)) return true; } return false; }
pub fn waitPre(self: *Rig, prefix: []const u8, mill: u32) bool { var tries: u32 = 0; while (tries < mill / 50) : (tries += 1) { if (self.hasRec(prefix)) return true; std.Io.sleep(self.iozz, .fromMilliseconds(50), .awake) catch {}; } return false; }
pub fn absOf(self: *Rig, rel: []const u8) ![]u8 { const cwd = try std.process.currentPathAlloc(self.iozz, self.aren.allocator()); return std.fs.path.join(self.aren.allocator(), &.{ cwd, ".zig-cache", "tmp", &self.tmpz.sub_path, rel }); }
pub fn waitRec(self: *Rig, kind: []const u8, mill: u32) ?[]const u8 { var tries: u32 = 0; while (tries < mill / 50) : (tries += 1) { if (self.mock.recFind(kind)) |rec| return rec; std.Io.sleep(self.iozz, .fromMilliseconds(50), .awake) catch {}; } return null; } };
